import z3
import time

def solve_qg3(n):
    x = [[z3.Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]
    s = z3.Solver()

    for i in range(n):
        for j in range(n):
            s.add(x[i][j] >= 0)
            s.add(x[i][j] <= n-1)

    # Latin square
    for i in range(n):
        s.add(z3.Distinct([x[i][j] for j in range(n)]))
        s.add(z3.Distinct([x[j][i] for j in range(n)]))

    # Idempotent
    for i in range(n):
        s.add(x[i][i] == i)

    # QG3
    for i in range(n):
        for j in range(n):
            a = x[i][j]
            b = x[j][i]
            for ai in range(n):
                for bi in range(n):
                    s.add(z3.Implies(z3.And(a == ai, b == bi), x[ai][bi] == i))

    print(f"n={n}: constraints={len(s.assertions())}")
    start = time.time()
    result = s.check()
    elapsed = time.time() - start
    print(f"Result: {result}, time: {elapsed:.2f}s")

    if result == z3.sat:
        m = s.model()
        grid = [[m.evaluate(x[i][j]).as_long() for j in range(n)] for i in range(n)]
        return grid
    return None

