import itertools

def check_qg3(grid, n):
    # Check Latin square
    for i in range(n):
        if sorted(grid[i]) != list(range(n)):
            return False
        if sorted([grid[j][i] for j in range(n)]) != list(range(n)):
            return False
    # Check idempotent
    for i in range(n):
        if grid[i][i] != i:
            return False
    # Check QG3
    for i in range(n):
        for j in range(n):
            a = grid[i][j]
            b = grid[j][i]
            if grid[a][b] != i:
                return False
    return True

